 3	public sealed class SliceApplication
 4	{
 5	    private const string UsageMessage = "Usage: slice <csv-file> select <columns> | where <expression> | sort <column> [asc|desc] | head <count> | distinct <column> [<column>...] | count | sum <column>";
 6	
 7	    private readonly Stream _output;
 8	    private readonly TextWriter _error;
 9	    private readonly CsvTableProcessor _csvProcessor = new();
10	
11	    public SliceApplication(Stream output, TextWriter error)
12	    {
13	        _output = output ?? throw new ArgumentNullException(nameof(output));
14	        _error = error ?? throw new ArgumentNullException(nameof(error));
15	    }
16	
17	    public async Task<int> RunAsync(IReadOnlyList<string> args)
18	    {
19	        if (!TryParseArguments(args, out var inputPath, out var command, out var commandArguments))
20	        {
21	            await _error.WriteLineAsync(UsageMessage);
22	            return 1;
23	        }
24	
25	        if (!File.Exists(inputPath))
26	        {
27	            await _error.WriteLineAsync($"File not found: {inputPath}");
28	            return 1;
29	        }
30	
31	        await using var input = File.OpenRead(inputPath);
32	
33	        string? result = command switch
34	        {
35	            "select" => await ExecuteSelectAsync(input, commandArguments[0]).ConfigureAwait(false),
36	            "where" => await _csvProcessor.WriteFilteredRowsAsync(input, _output, commandArguments[0]).ConfigureAwait(false),
37	            "sort" => await _csvProcessor.WriteSortedRowsAsync(input, _output, commandArguments[0], commandArguments.Count > 1 ? commandArguments[1] : null).ConfigureAwait(false),
38	            "head" => await _csvProcessor.WriteHeadRowsAsync(input, _output, commandArguments[0]).ConfigureAwait(false),
39	            "distinct" => await ExecuteDistinctAsync(input, commandArguments).ConfigureAwait(false),
40	            "count" => await _csvProcessor.WriteCountAsync(input, _output).ConfigureAwait(false),
41	            "sum" => await _csvProcessor.WriteSumAsync(input, _output, commandArguments[0]).ConfigureAwait(false),
42	            _ => UsageMessage
43	        };
44	
45	        if (result is null)
46	        {
47	            return 0;
48	        }
49	
50	        await _error.WriteLineAsync(result);
51	        return 1;
52	    }
53	
54	    private Task<string?> ExecuteSelectAsync(Stream input, string columnsArgument)
55	    {
56	        IReadOnlyList<string> selectedColumns = _csvProcessor.ParseRequestedColumns(columnsArgument);
57	        return _csvProcessor.WriteSelectedColumnsAsync(input, _output, selectedColumns);
58	    }
59	
60	    private Task<string?> ExecuteDistinctAsync(Stream input, IReadOnlyList<string> columnArguments)
61	    {
62	        IReadOnlyList<string> distinctColumns = _csvProcessor.ParseRequestedColumns(columnArguments);
63	        return _csvProcessor.WriteDistinctRowsAsync(input, _output, distinctColumns);
64	    }
65	
66	    private static bool TryParseArguments(
67	        IReadOnlyList<string> args,
68	        out string inputPath,
69	        out string command,
70	        out IReadOnlyList<string> commandArguments)
71	    {
72	        inputPath = string.Empty;
73	        command = string.Empty;
74	        commandArguments = Array.Empty<string>();
75	
76	        if (args.Count < 2)
77	        {
78	            return false;
79	        }
80	
81	        inputPath = args[0];
82	        command = args[1];
83	        commandArguments = args.Count > 2 ? args.Skip(2).ToArray() : Array.Empty<string>();
84	
85	        return command switch
86	        {
87	            "select" or "where" or "head" => commandArguments.Count == 1,
88	            "sort" => commandArguments.Count is 1 or 2,
89	            "distinct" => commandArguments.Count >= 1,
90	            "count" => commandArguments.Count == 0,
91	            "sum" => commandArguments.Count == 1,
92	            _ => false
93	        };
94	    }
95	}

